{
  "tasks": [
    {
      "task_id": "T01",
      "title": "整体销售概况",
      "business_question": "总体销售额、订单数量及平均单笔金额是多少？",
      "priority": "P0",
      "priority_reason": "探索性分析的基础，提供核心指标的总体量级和分布特征，删除后无法建立对数据规模的基本认知。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales"
              },
              {
                "function": "count",
                "field": null,
                "alias": "order_count"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_order_value"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "地区维度差异分析",
      "business_question": "各地区的销售额贡献和订单数量分布如何？是否存在显著的地区差异？",
      "priority": "P0",
      "priority_reason": "识别主要业务区域的表现差异，是探索“差异”这一核心目标的关键视角。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_by_region"
              },
              {
                "function": "count",
                "field": null,
                "alias": "orders_by_region"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "sales_by_region",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "产品类别表现分析",
      "business_question": "不同产品类别的销售总额和订单量分别是多少？哪类产品销售更集中？",
      "priority": "P0",
      "priority_reason": "从产品结构角度探索业务特征，识别主力品类，支持对“主要特征”的分析。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_by_category"
              },
              {
                "function": "count",
                "field": null,
                "alias": "orders_by_category"
              }
            ],
            "dimensions": [
              "field_0007"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "sales_by_category",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T04",
      "title": "月度销售趋势",
      "business_question": "按月统计的销售额变化趋势如何？是否存在季节性波动或异常月份？",
      "priority": "P1",
      "priority_reason": "时间序列分析有助于发现“规律”和“趋势”，但鉴于样本量较小（10行），其解释力有限，作为补充视角。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "month_num"
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "monthly_sales"
              }
            ],
            "dimensions": [
              "month_num"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "month_num",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
